      SUBROUTINE SECORDCC     CALCULATES NUMERICAL VALUE OF SECOND-ORDER MATRIX ELEMENTSCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BETAC.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM1F.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4B.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM19.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'R.CIN'      INCLUDE 'T.CIN'C ----------------------------------------------------------------------      INTEGER         VARST      EXTERNAL        IDATAC      IF (TYPE .EQ. 14 .AND. TYP1 .EQ. 14) GO TO 1400      DO 11 IA = 1, 105   11 TL(IA) = 0.0      IF (RI .NE. 0.0) THEN        GI2 = SM**2/(SM**2 + RI**2)      ELSE        GI2 = 0.0      ENDIF      GO TO (5100, 200, 300, 400, 500,5200,5200,5200,5200,5200,     1       5200,5200,5200,1400,5200,5200,5200,1800,1900,5000,     2       5200,5200,5200,5200,5100,5200,5200,5200,5200,5200,     3       5200,5200,5200,3400,3500,3500,5200,5200,5200,5200,     4       5200,5200,5200,5200,5200,5200,5200,5200), TYPECCC     2. -- POLE FACE ROTATIONC  200 CALL FRING2      GO TO 5100CC     3. -- DRIFT SPACEC  300 TANFO = TAN(FOTILT/RADIAN)      T(3,7) = TANFO      T(1,2) = TANFO  310 T(5,3) = - 0.5*L      T(5,10) = - 0.5*L      GO TO 5000CC     4. -- BENDING MAGNETC  400 IF (H0 .EQ. 0) GO TO 310      RH = 1.0 + RMPS      H = H0*RH      HEX = RMPS*H0      BEB = BDB/(H0*UNITI(1))**2      CALL SECORSC  410 IF (RNMS .EQ. 0.0 .AND. VARST(NRNMS) .EQ. 0) GO TO 480      IF ((VRN .EQ. 0.0 .AND. NPN .EQ. 0.0 .AND. BDBP .EQ. 0.0)     1     .AND. (VARST(NVR) .EQ. 0 .AND. VARST(NNP) .EQ. 0     2     .AND. VARST(NK1P) .EQ. 0 .AND. VARST(NBDBP) .EQ. 0)     3     .AND. VARST(NK2P) .EQ. 0) GO TO 480      NBR = RH*NB      VR = RNMS*VRN      NPR = RNMS*NPN      BEP = RNMS*BDBP/(H0*UNITI(1))**2      CALL SECORN  480 GO TO 5000CC     5. -- QUADRUPOLEC  500 JQUAD = 1      KQ2 = KX2      CALL FOCUS2      JQUAD = 3      KQ2 = KY2      CALL FOCUS2      GO TO 5000CC     14. -- ARBITRARY MATRIXC 1400 I14S = IDATA(I+8)      IF (I14S .NE. 0) GO TO 1420      IX = I + 9      IND0 = 0      DO 1410 J = 1, 6      IND0 = IND0 + J      IND = IND0      DO 1408 K = J, 6, 1      T(J1,IND) = DATA(IX)*UBEAM(J1)/(UBEAM(J)*UBEAM(K))      IND = IND + K      IX = IX + 1 1408 CONTINUE 1410 CONTINUE 1420 IF (NDIF .EQ. 1 .AND. NUM + 1 .GT. NEL) GO TO 5100      IF (NDIF .EQ. -1 .AND. NUM - 1 .LE. 0) GO TO 5100      GO TO 5100CC     18. -- SEXTUPOLEC 1800 CALL SEXT2      GO TO 5000CC     19. -- SOLENOIDC 1900 CS = COS(KL)      SN = SIN(KL)      TEMP = 0.5*KO*L*SN      T(1,16) = TEMP      T(2,17) = TEMP      T(3,18) = TEMP      T(4,19) = TEMP      T(1,17) = SN/KO - L*CS      T(3,19) = T(1,17)      TEMP = - 0.5*KO*L*CS      T(1,18) = TEMP      T(2,19) = TEMP      T(4,17) = - TEMP      T(3,16) = - TEMP      T(1,19) = (1.0 - CS)/KO - L*SN      T(3,17) = - T(1,19)      T(2,16) = 0.25*KO*(KO*L*CS + SN)      T(4,18) = T(2,16)      T(2,18) = 0.25*KO*(1.0 - CS + KO*L*SN)      T(4,16) = - T(2,18)      T(5,3) = - 0.5*L      T(5,10) = - 0.5*L      GO TO 5000CC     34. -- PLASMA LENSC 3400 J = 1      KQ2 = KX2 3410 CS = R(J,J)      SK = - R(J+1,J)      SN = R(J,J+1)      T(J,J+15) = SK * L / 2.      T(J+1,J+16) = SK * L / 2.      T(J,J+16) = (SN - L*CS)/2.0      T(J+1,J+15) = (SK + KQ2*L*CS)/2.0      T(5,J*(J+1)/2) = - 0.25*KQ2*(L - SN*CS)      T(5,J*(J+3)/2) = 0.5*SN*SK      T(5,J*(J+3)/2+1) = - 0.25*(L + CS*SN)      IF (J .NE. 1) GO TO 5000      J = 3      KQ2 = KY2      GO TO 3410CC     35. -- HKICK -- HORIZONTAL VERNIERC                     ORC     36. -- VKICK -- VERTICAL VERNIERC 3500 T(1,3) = - 0.75*H0*L**2      T(1,10) = - 0.25*H0*L**2      T(1,21) = - 0.5*H0*L**2      T(2,3) = - 1.5*H0*L      T(2,10) = - 0.5*H0*L      T(2,21) = - H0*L      T(3,8) = - 0.5*H0*L**2      T(4,8) = - H0*L      T(5,3) = - 0.5*L      T(5,10) = - 0.5*L      T(5,17) = - 0.5*H0*L**2      GO TO 5000CC     PATH LENGTH TERMSC 5000 T(5,21) = T(5,21) - 1.5*L*BETA**2*GI2CC     CHANGE TRIANGULAR MATRIX INTO SQUARE MATRIXC 5100 IF (NORD1 .GE. 3) CALL THOR 5200 CONTINUE      RETURN      END